

/**
 * SERVER-SIDE ONLY ENDPOINT: Supabase Auth Send SMS Hook
 * Receives OTP generated by Supabase Auth GoTrue Server
 * Dispatches DLT-approved SMS via Fast2SMS API
 * 
 * NEVER EXPOSES FAST2SMS_API_KEY TO BROWSER / CLIENT
 */
export async function handleSendSmsHook(reqBody, headers = {}) {
  // 1. Optional Signature / Secret Authorization Check
  const hookSecret = process.env.SEND_SMS_HOOK_SECRET;
  if (hookSecret) {
    const authHeader = headers['authorization'] || headers['Authorization'] || headers['x-supabase-auth-secret'] || '';
    const token = authHeader.replace(/^Bearer\s+/i, '').trim();
    if (token !== hookSecret) {
      return {
        status: 401,
        body: { error: 'Unauthorized: Invalid Supabase Auth Hook Secret.' }
      };
    }
  }

  // 2. Extract User Phone and Supabase Generated OTP
  const rawPhone = reqBody?.user?.phone || reqBody?.phone || reqBody?.record?.phone || '';
  const otpCode = reqBody?.sms?.otp || reqBody?.otp || reqBody?.record?.otp || '';

  if (!rawPhone || !otpCode) {
    return {
      status: 400,
      body: { error: 'Bad Request: Missing phone number or OTP in hook payload.' }
    };
  }

  // Normalize phone number to 10-digit Indian mobile format for Fast2SMS API
  const cleanDigits = rawPhone.replace(/\D/g, '');
  const tenDigitPhone = cleanDigits.length >= 10 ? cleanDigits.slice(-10) : cleanDigits;

  if (tenDigitPhone.length !== 10) {
    return {
      status: 400,
      body: { error: `Invalid phone format: ${rawPhone}` }
    };
  }

  // 3. Retrieve Fast2SMS API Authorization Key from server environment
  const fast2smsApiKey = process.env.FAST2SMS_API_KEY;

  // Fallback for development if Fast2SMS API Key is not set on Vercel environment
  if (!fast2smsApiKey) {
    console.info(`ℹ️ [Dev Mode] Fast2SMS API Key not set. Simulated SMS OTP for +91${tenDigitPhone}: [${otpCode}]`);
    return {
      status: 200,
      body: {
        success: true,
        message: `[Dev Mode] SMS OTP ${otpCode} processed for +91${tenDigitPhone}`
      }
    };
  }

  // 4. Send SMS via Fast2SMS DLT-Approved API
  try {
    const entityId = '1001115599739958205';
    const senderId = 'HELTEX';
    const dltMessageId = process.env.FAST2SMS_TEMPLATE_ID || '178652'; // DLT approved OTP template ID

    // Build Fast2SMS API Request
    const fast2smsUrl = new URL('https://www.fast2sms.com/dev/bulkV2');
    fast2smsUrl.searchParams.append('authorization', fast2smsApiKey);
    fast2smsUrl.searchParams.append('route', 'dlt');
    fast2smsUrl.searchParams.append('sender_id', senderId);
    fast2smsUrl.searchParams.append('message', dltMessageId);
    fast2smsUrl.searchParams.append('variables_values', String(otpCode));
    fast2smsUrl.searchParams.append('numbers', tenDigitPhone);

    const response = await fetch(fast2smsUrl.toString(), {
      method: 'GET',
      headers: {
        'Accept': 'application/json'
      }
    });

    const resJson = await response.json();

    if (!response.ok || resJson.return === false) {
      console.error('Fast2SMS API Delivery Error:', resJson);
      return {
        status: 500,
        body: { error: resJson.message || 'Fast2SMS OTP delivery failed.' }
      };
    }

    console.info(`✅ Fast2SMS OTP successfully dispatched to +91${tenDigitPhone}`);
    return {
      status: 200,
      body: {
        success: true,
        message: 'OTP SMS sent successfully via Fast2SMS'
      }
    };
  } catch (err) {
    console.error('Fast2SMS Send Hook Exception:', err);
    return {
      status: 500,
      body: { error: err.message || 'Internal server error sending SMS.' }
    };
  }
}

/**
 * VERCEL SERVERLESS FUNCTION HANDLER
 */
export default async function handler(req, res) {
  if (req.method !== 'POST') {
    return res.status(405).json({ error: 'Method Not Allowed. Use POST.' });
  }

  const result = await handleSendSmsHook(req.body, req.headers);
  return res.status(result.status).json(result.body);
}
